// New extension, modeled on the real GetClockEntry's nullable contract
public bool TryGetOpenEntry(int employeeId, out ClockEntry? entry)
{
    entry = _clockEntries.FirstOrDefault(e => e.EmployeeId == employeeId && e.ClockOut is null);
    return entry is not null;
}

// Illustrative only -- not used anywhere in this codebase
static void ReplaceIfClosed(ref ClockEntry entry, ClockEntry replacement)
{
    if (entry.ClockOut is not null) entry = replacement;   // reassigns the CALLER's variable
}
